<?php require __DIR__.'/config.php';$u=require_login();$b=require_business();if(!can('orders')){http_response_code(403);exit('Forbidden');}$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=$_POST['action']??'';$allowed=['accepted','preparing','ready','serving','served','completed','cancelled'];if(in_array($action,$allowed,true)){try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM orders WHERE id=? AND business_id=? FOR UPDATE");$s->execute([$id,$b['id']]);$o=$s->fetch();if(!$o)throw new RuntimeException('Order not found.');$from=$o['status'];if($from===$action){$pdo->commit();flash('Order is already '.strtolower($action).'.');redirect('orders.php');}$transitions=['new'=>['accepted','cancelled'],'accepted'=>['preparing','cancelled'],'preparing'=>['ready','cancelled'],'ready'=>['serving','cancelled'],'serving'=>['served','cancelled'],'served'=>['completed'],'completed'=>[],'cancelled'=>[]];if(!in_array($action,$transitions[$from]??[],true))throw new RuntimeException('Invalid status transition from '.strtoupper($from).' to '.strtoupper($action).'.');$assigned=$o['assigned_to'];$servedBy=$o['served_by'];if(in_array($action,['serving','served','completed'],true))$assigned=$u['id'];if($action==='served'||$action==='completed')$servedBy=$u['id'];$s=$pdo->prepare("UPDATE orders SET status=?,assigned_to=?,served_by=?,served_at=CASE WHEN ? IN ('served','completed') THEN NOW() ELSE served_at END,updated_at=NOW() WHERE id=? AND business_id=? AND status=?");$s->execute([$action,$assigned,$servedBy,$action,$id,$b['id'],$from]);if($s->rowCount()!==1)throw new RuntimeException('Order changed before this action was saved. Please refresh.');$h=$pdo->prepare("INSERT INTO order_status_history(order_id,business_id,user_id,from_status,to_status,created_at) VALUES(?,?,?,?,?,NOW())");$h->execute([$id,$b['id'],$u['id'],$from,$action]);$pdo->commit();notify_business((int)$b['id'],'Order #'.$o['order_number'],'Order status: '.strtoupper($action),$u['id'],'orders.php','orders');flash('Order updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Could not update order: '.$e->getMessage(),'error');}}redirect('orders.php');}
$s=$pdo->prepare("SELECT o.*,l.name location_name,ot.name outlet_name,au.name assigned_name,su.name served_name FROM orders o LEFT JOIN locations l ON l.id=o.location_id LEFT JOIN outlets ot ON ot.id=o.outlet_id LEFT JOIN users au ON au.id=o.assigned_to LEFT JOIN users su ON su.id=o.served_by WHERE o.business_id=? ORDER BY o.created_at DESC LIMIT 100");$s->execute([$b['id']]);$orders=$s->fetchAll();include __DIR__.'/app/layout_top.php';?><div class="page-head"><div><div class="eyebrow">Live operations</div><h1>Orders</h1><p>Every status change is tied to a staff account.</p></div></div><div class="alert" id="alertControls"><b>Order alerts</b><div class="small muted">Tap once on this phone to enable browser notifications and sound. SERV will then watch for new orders while this dashboard is open.</div><button class="btn gold" id="enableAlerts" type="button" style="margin-top:10px">Enable alerts & sound</button></div><div id="liveNotice"></div><?php foreach($orders as $o):?><article class="order-card"><div class="order-top"><div><b>#<?=e($o['order_number'])?></b><span class="badge"><?=e(strtoupper($o['status']))?></span><div class="small muted"><?=e($o['location_name']??'General')?> · <?=e($o['outlet_name']??'General')?> · <?=e($o['created_at'])?></div></div><strong><?=money((float)$o['total'])?></strong></div><div class="small">Assigned: <b><?=e($o['assigned_name']??'Unassigned')?></b> · Served by: <b><?=e($o['served_name']??'Not yet')?></b></div><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$o['id']?>"><?php foreach(['accepted'=>'Accept','preparing'=>'Preparing','ready'=>'Ready','serving'=>'On the way','served'=>'Served','completed'=>'Complete'] as $k=>$v):?><button class="btn <?=($k==='served'?'gold':'')?>" name="action" value="<?=$k?>"><?=$v?></button><?php endforeach;?></form></div></article><?php endforeach;if(!$orders):?><div class="panel"><p class="muted">No orders yet.</p></div><?php endif;?><script>(function(){let last=Number(localStorage.getItem('serv_last_notification')||0);let enabled=localStorage.getItem('serv_alerts_enabled')==='1';let audioCtx=null;function unlock(){try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume()}catch(e){}}function beep(){unlock();if(!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=880;g.gain.value=.18;o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.35);setTimeout(()=>{try{const o2=audioCtx.createOscillator(),g2=audioCtx.createGain();o2.frequency.value=1100;g2.gain.value=.14;o2.connect(g2);g2.connect(audioCtx.destination);o2.start();o2.stop(audioCtx.currentTime+.35)}catch(e){}},420)}function enable(){enabled=true;localStorage.setItem('serv_alerts_enabled','1');unlock();if('Notification'in window&&Notification.permission==='default')Notification.requestPermission();const b=document.getElementById('enableAlerts');if(b)b.textContent='Alerts enabled ✓'}document.addEventListener('click',unlock,{passive:true});document.addEventListener('touchstart',unlock,{passive:true});document.getElementById('enableAlerts')?.addEventListener('click',enable);if(enabled){const b=document.getElementById('enableAlerts');if(b)b.textContent='Alerts enabled ✓'}async function poll(){try{const r=await fetch('api/notifications.php?after='+last,{cache:'no-store'});const d=await r.json();if(!d.ok)return;for(const n of d.notifications){last=Math.max(last,n.id);localStorage.setItem('serv_last_notification',String(last));if(enabled){if(window.SERV&&SERV.announce)SERV.announce(n.title,n.body);else beep();if('Notification'in window&&Notification.permission==='granted'){const no=new Notification(n.title,{body:n.body,icon:'assets/icon.svg',tag:'serv-'+n.id});no.onclick=()=>{window.location.href=n.url||'orders.php'}}}const box=document.getElementById('liveNotice');if(box){box.innerHTML='<div class="alert success"><b>'+n.title+'</b><div class="small">'+n.body+'</div></div>'}if(n.url&&/orders\.php/.test(n.url)){setTimeout(()=>location.reload(),800)}}}catch(e){}}poll();setInterval(poll,3000)})();</script><?php include __DIR__.'/app/layout_bottom.php';
